function leastTotalWalk(grid: number[][]): number {
  const rows: number[] = [], cols: number[] = [];
  const R = grid.length, C = grid[0].length;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) if (grid[r][c] === 1) rows.push(r);
  for (let c = 0; c < C; c++) for (let r = 0; r < R; r++) if (grid[r][c] === 1) cols.push(c);
  const spread = (a: number[]): number => {
    let lo = 0, hi = a.length - 1, total = 0;
    while (lo < hi) total += a[hi--] - a[lo++];
    return total;
  };
  return spread(rows) + spread(cols);
}

