class Solution:
    def leastTotalWalk(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        rows = [r for r in range(R) for c in range(C) if grid[r][c] == 1]
        cols = [c for c in range(C) for r in range(R) if grid[r][c] == 1]

        def spread(a: List[int]) -> int:
            lo, hi, total = 0, len(a) - 1, 0
            while lo < hi:
                total += a[hi] - a[lo]
                lo += 1
                hi -= 1
            return total

        return spread(rows) + spread(cols)

